From 4282c875463c4d83f4e6c4037e3c85172d655658 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:32:56 +0100
Subject: [PATCH] sqlite: Recover from a corrupted resources database

A corrupted database made every query fail, which aborts on debug builds
and otherwise keeps failing forever, losing favourites and recent files.
Check the database at startup and replace a broken one with the backup.

BUG: 389441
---
 src/service/plugins/sqlite/Database.cpp | 43 +++++++++++++++++++++++++
 src/service/plugins/sqlite/Utils.h      |  1 -
 2 files changed, 43 insertions(+), 1 deletion(-)

diff --git a/src/service/plugins/sqlite/Database.cpp b/src/service/plugins/sqlite/Database.cpp
index b4138bf5..89a10cb4 100644
--- a/src/service/plugins/sqlite/Database.cpp
+++ b/src/service/plugins/sqlite/Database.cpp
@@ -10,6 +10,8 @@

 // Qt
 #include <QDir>
+#include <QSqlDatabase>
+#include <QSqlQuery>
 #include <QStandardPaths>

 // Utils
@@ -120,6 +122,25 @@ void ResourcesDatabaseInitializer::initDatabase(bool retryOnFail)
                });
     };

+    auto databaseIsCorrupt = [](const QDir &dir) {
+        const QString connectionName = QStringLiteral("kactivities_db_resources_check");
+        bool corrupt = false;
+        {
+            auto database = QSqlDatabase::addDatabase(QStringLiteral("QSQLITE"), connectionName);
+            database.setConnectOptions(QStringLiteral("QSQLITE_OPEN_READONLY"));
+            database.setDatabaseName(dir.filePath(QStringLiteral("database")));
+            if (database.open()) {
+                QSqlQuery query(QStringLiteral("PRAGMA quick_check"), database);
+                const auto errorCode = query.lastError().nativeErrorCode();
+                corrupt =
+                    errorCode == QLatin1String("11") || errorCode == QLatin1String("26") || (query.next() && query.value(0).toString() != QLatin1String("ok"));
+            }
+            database.close();
+        }
+        QSqlDatabase::removeDatabase(connectionName);
+        return corrupt;
+    };
+
     // First, let's move the files from `resources-test-backup` to
     // `resources-working-backup` (if they exist)
     if (databaseFilesExistIn(databaseTestBackupDirectory)) {
@@ -132,6 +153,28 @@ void ResourcesDatabaseInitializer::initDatabase(bool retryOnFail)
         }
     }

+    // If the current database is corrupted, move it aside and fall
+    // back to the last working backup, or to a new empty database
+    if (QFile::exists(databaseDirectory.filePath(QStringLiteral("database"))) && databaseIsCorrupt(databaseDirectory)) {
+        qCWarning(KAMD_LOG_RESOURCES) << "The database is corrupted, moving it to database.corrupt";
+        for (const auto &fileName : databaseFiles) {
+            const auto filePath = databaseDirectory.filePath(fileName);
+            QFile::remove(filePath + QStringLiteral(".corrupt"));
+            if (QFile::exists(filePath)) {
+                QFile::rename(filePath, filePath + QStringLiteral(".corrupt"));
+            }
+        }
+
+        if (databaseFilesExistIn(databaseWorkingBackupDirectory)) {
+            qCWarning(KAMD_LOG_RESOURCES) << "Loading the latest working version of the database";
+            if (!copyDatabaseFiles(databaseWorkingBackupDirectory, databaseDirectory) || databaseIsCorrupt(databaseDirectory)) {
+                qCWarning(KAMD_LOG_RESOURCES) << "The working backup is not usable, creating a new database";
+                removeDatabaseFiles(databaseDirectory);
+                removeDatabaseFiles(databaseWorkingBackupDirectory);
+            }
+        }
+    }
+
     // Next, copy the current database files to `resources-test-backup`
     if (databaseFilesExistIn(databaseDirectory)) {
         qCDebug(KAMD_LOG_RESOURCES) << "Creating the backup of the current database...";
diff --git a/src/service/plugins/sqlite/Utils.h b/src/service/plugins/sqlite/Utils.h
index 9e7e591a..05b7d541 100644
--- a/src/service/plugins/sqlite/Utils.h
+++ b/src/service/plugins/sqlite/Utils.h
@@ -50,7 +50,6 @@ inline bool exec(Common::Database &database, ErrorHandling eh, QSqlQuery &query)
             qCWarning(KAMD_LOG_RESOURCES) << query.lastError();
             KCrash::setErrorMessage(query.lastError().text());
         }
-        Q_ASSERT_X(success, "Uils::exec", qPrintable(QStringLiteral("Query failed:") + query.lastError().text()));

         if (!success) {
             database.reportError(query.lastError());
